import {escape} from '../renderer/svg.js';import {find,locate,walk,clone,isLocked} from '../document/model.js';import {putKey} from '../animation/evaluate.js';
const names={x:'Position X',y:'Position Y',rotation:'Rotation',scaleX:'Scale X',scaleY:'Scale Y',opacity:'Opacity',fill:'Fill',stroke:'Stroke',strokeWidth:'Stroke width',nodes:'Path shape'};
export class Timeline{constructor(a){this.a=a;this.el=document.querySelector('#timeline-content');this.scroll=document.querySelector('#timeline-scroll');this.zoom=1;this.collapsed=new Set();this.pointers=new Map();this.clipboard=[];this.scroll.addEventListener('pointerdown',e=>this.down(e));this.scroll.addEventListener('pointermove',e=>this.move(e));this.scroll.addEventListener('pointerup',e=>this.up(e));this.scroll.addEventListener('pointercancel',e=>this.cancel(e));this.el.addEventListener('click',e=>this.click(e));}
width(){return Math.max(500,this.scroll.clientWidth-244)*this.zoom;}px(t){return t/this.a.doc.duration*this.width();}time(e){const lane=this.el.querySelector('.track-lane'),r=lane.getBoundingClientRect();return Math.max(0,Math.min(this.a.doc.duration,(e.clientX-r.left)/this.width()*this.a.doc.duration));}frame(t){return Math.round(t*this.a.doc.fps)/this.a.doc.fps;}
render(){const a=this.a,p=a.doc,w=this.width();this.el.style.setProperty('--track',w+'px');this.el.style.setProperty('--second',w/p.duration+'px');let html=`<div class="timeline-row ruler"><div class="layer-label">LAYERS <span style="margin-left:auto;padding-right:14px">${p.fps} FPS</span></div><div class="track-lane" data-scrub>${Array.from({length:Math.ceil(p.duration)+1},(_,i)=>`<span class="ruler-mark" style="left:${i/p.duration*100}%">${i}s</span>`).join('')}</div></div>`;const renderNodes=(list,depth)=>{for(let i=list.length-1;i>=0;i--){const n=list[i],tracks=Object.entries(n.tracks).filter(([,t])=>t.length),closed=this.collapsed.has(n.id);html+=`<div class="timeline-row ${a.selected.includes(n.id)?'selected':''}" data-layer="${n.id}"><div class="layer-label" style="padding-left:${8+depth*12}px"><button class="reorder" data-reorder="${n.id}" aria-label="Reorder ${escape(n.name)}">⠿</button><button data-collapse="${n.id}" aria-label="${closed?'Expand':'Collapse'} layer" aria-expanded="${!closed}">${n.type==='group'||tracks.length?(closed?'›':'⌄'):'·'}</button><button class="layer-name" data-select="${n.id}" title="${escape(n.name)}">${escape(n.name)}</button><button data-visible="${n.id}" aria-label="${n.visible?'Hide':'Show'} layer">${n.visible?'◉':'○'}</button><button data-lock="${n.id}" aria-label="${n.locked?'Unlock':'Lock'} layer">${n.locked?'🔒':'🔓'}</button></div><div class="track-lane" data-scrub>${closed?tracks.flatMap(([prop,t])=>t.map(k=>this.key(n,prop,k))).join(''):''}</div></div>`;if(!closed){for(const [prop,track] of tracks)html+=`<div class="timeline-row property-row" data-layer="${n.id}"><div class="layer-label">${names[prop]||prop}</div><div class="track-lane" data-scrub>${track.map(k=>this.key(n,prop,k)).join('')}</div></div>`;renderNodes(n.children||[],depth+1);}}};renderNodes(p.layers,0);html+=`<div class="timeline-row audio-row ${p.audio?'has-audio':'empty-audio'}"><div class="layer-label">♫ <button class="layer-name" id="waveform-label">${p.audio?escape(p.audio.name):'Audio track'}</button>${p.audio?`<button data-audio-mute aria-label="Mute audio">${p.audio.muted?'○':'◉'}</button>`:''}</div><div class="track-lane" data-scrub>${p.audio?`<div class="audio-clip" data-audio-clip style="left:${p.audio.offset/p.duration*100}%;width:${(p.audio.trimEnd-p.audio.trimStart)/p.duration*100}%"><canvas aria-label="Audio waveform"></canvas></div>`:'<span class="empty-track">Record a voice or import audio</span>'}</div></div>`;if(!p.layers.length)html+='<div class="timeline-row"><div class="layer-label subtle">Your artwork appears here</div><div class="track-lane" data-scrub></div></div>';html+='<div class="playhead"></div>';this.el.innerHTML=html;this.playhead();this.waveform();document.querySelector('#timeline-scale').textContent=this.zoom.toFixed(1)+'×';}
key(n,prop,k){return `<button class="key-hit ${this.a.keyIds.has(k.id)?'selected':''}" data-keyid="${k.id}" data-object="${n.id}" data-property="${prop}" style="left:${k.time/this.a.doc.duration*100}%" title="${names[prop]} · ${k.time.toFixed(2)}s · ${k.easing}" aria-label="${names[prop]} keyframe at ${k.time.toFixed(2)} seconds"><span class="diamond"></span></button>`;}
playhead(){const label=this.el.querySelector('.layer-label');this.el.querySelector('.playhead')?.style.setProperty('left',(label?.offsetWidth||244)+this.px(this.a.time)+'px');}
keys(){const out=[];walk(this.a.doc.layers,n=>Object.entries(n.tracks).forEach(([prop,t])=>t.forEach(k=>{if(this.a.keyIds.has(k.id))out.push({n,prop,k});})));return out;}
down(e){if(this.a.audio.recording||this.a.audio.pending||this.a.audio.finalizing)return;if(e.button!==0||e.target.closest('input,select'))return;const lane=e.target.closest('.track-lane'),reorder=e.target.closest('[data-reorder]');if(!lane&&!reorder)return;this.a.properties.flush();this.a.stage.finishPath();this.pointers.set(e.pointerId,e);if(this.pointers.size===1)this.owner=e.pointerId;e.preventDefault();this.a.pause();this.scroll.setPointerCapture(e.pointerId);if(this.pointers.size===2){if(this.g?.edit)this.a.history.cancel();const p=[...this.pointers.values()];this.g={type:'pinch',distance:Math.hypot(p[1].clientX-p[0].clientX,p[1].clientY-p[0].clientY),zoom:this.zoom,scroll:this.scroll.scrollLeft,top:this.scroll.scrollTop,mid:{x:(p[0].clientX+p[1].clientX)/2,y:(p[0].clientY+p[1].clientY)/2}};this.render();return;}const hit=e.target.closest('[data-keyid]');if(hit){if(isLocked(this.a.doc,hit.dataset.object))return;const id=hit.dataset.keyid;if(this.a.multi||e.shiftKey){if(this.a.keyIds.has(id))this.a.keyIds.delete(id);else this.a.keyIds.add(id);}else if(!this.a.keyIds.has(id))this.a.keyIds=new Set([id]);this.a.selected=[hit.dataset.object];this.a.properties.render();this.a.renderStage();const items=this.keys().map(x=>({...x,time:x.k.time}));this.a.history.begin();this.g={type:'keys',edit:true,start:e.clientX,items};this.render();}else if(reorder){if(isLocked(this.a.doc,reorder.dataset.reorder))return;this.a.history.begin();this.g={type:'reorder',edit:true,id:reorder.dataset.reorder,start:e.clientY};}else if(e.target.closest('[data-audio-clip]')){this.a.history.begin();this.g={type:'audio',edit:true,start:e.clientX,offset:this.a.doc.audio.offset};}else if(lane){this.g={type:'scrub'};this.a.seek(this.frame(this.time(e)));}}
move(e){if(!this.pointers.has(e.pointerId)||(this.g?.type!=='pinch'&&e.pointerId!==this.owner))return;this.pointers.set(e.pointerId,e);const g=this.g;if(!g)return;e.preventDefault();if(g.type==='pinch'){const p=[...this.pointers.values()];if(p.length<2)return;this.zoom=Math.max(.5,Math.min(8,g.zoom*Math.hypot(p[1].clientX-p[0].clientX,p[1].clientY-p[0].clientY)/Math.max(30,g.distance)));this.el.style.setProperty('--track',this.width()+'px');this.el.style.setProperty('--second',this.width()/this.a.doc.duration+'px');this.scroll.scrollLeft=Math.max(0,g.scroll+g.mid.x-(p[0].clientX+p[1].clientX)/2);this.scroll.scrollTop=Math.max(0,g.top+g.mid.y-(p[0].clientY+p[1].clientY)/2);document.querySelector('#timeline-scale').textContent=this.zoom.toFixed(1)+'×';this.playhead();return;}if(g.type==='scrub')this.a.seek(this.frame(this.time(e)));else if(g.type==='keys'){let delta=this.frame((e.clientX-g.start)/this.width()*this.a.doc.duration);const min=Math.min(...g.items.map(i=>i.time)),max=Math.max(...g.items.map(i=>i.time));delta=Math.max(-min,Math.min(this.a.doc.duration-max,delta));for(const x of g.items)x.k.time=x.time+delta;for(const {n,prop} of g.items)n.tracks[prop].sort((a,b)=>a.time-b.time);for(const x of g.items){this.el.querySelector(`[data-keyid="${x.k.id}"]`)?.style.setProperty('left',x.k.time/this.a.doc.duration*100+'%');}this.a.renderStage();}else if(g.type==='audio'){this.a.doc.audio.offset=Math.max(0,Math.min(this.a.doc.duration,this.frame(g.offset+(e.clientX-g.start)/this.width()*this.a.doc.duration)));this.el.querySelector('.audio-clip')?.style.setProperty('left',this.a.doc.audio.offset/this.a.doc.duration*100+'%');}else if(g.type==='reorder'){this.dropId=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-layer]')?.dataset.layer;}}
up(e){if(this.g?.type!=='pinch'&&e.pointerId!==this.owner){this.pointers.delete(e.pointerId);return;}this.pointers.delete(e.pointerId);const g=this.g;if(!g)return;if(g.type==='pinch'){if(!this.pointers.size){this.g=null;this.render();}return;}if(g.type==='reorder'&&this.dropId&&this.dropId!==g.id){const src=locate(this.a.doc,g.id),dst=locate(this.a.doc,this.dropId);if(src.list===dst.list){src.list.splice(src.index,1);const target=src.list.findIndex(n=>n.id===this.dropId);src.list.splice(target+(e.clientY>g.start?0:1),0,src.node);}else this.a.toast('Reorder layers within the same group.');this.dropId=null;}if(g.type==='keys'){for(const {n,prop,k} of g.items){n.tracks[prop]=n.tracks[prop].filter(other=>other.id===k.id||Math.abs(other.time-k.time)>.00001);}}if(g.edit)this.a.history.commit('Timeline gesture');this.g=null;this.a.render();}
cancel(e){if(this.g?.type!=='pinch'&&e.pointerId!==this.owner){this.pointers.delete(e.pointerId);return;}this.pointers.delete(e.pointerId);if(this.g?.edit)this.a.history.cancel();this.g=null;this.a.render();}
click(e){const a=this.a,id=e.target.closest('[data-select]')?.dataset.select;if(id){if(a.multi||e.shiftKey)a.selected=a.selected.includes(id)?a.selected.filter(x=>x!==id):[...a.selected,id];else a.selected=[id];a.nodeEdit=false;a.render();return;}for(const [attr,prop] of [['visible','visible'],['lock','locked']]){const id=e.target.closest(`[data-${attr}]`)?.dataset[attr];if(id)return a.mutate('Layer '+prop,()=>{const n=find(a.doc,id);n[prop]=!n[prop];});}const collapse=e.target.closest('[data-collapse]')?.dataset.collapse;if(collapse){this.collapsed.has(collapse)?this.collapsed.delete(collapse):this.collapsed.add(collapse);this.render();}if(e.target.closest('[data-audio-mute]'))a.mutate('Mute audio',()=>a.doc.audio.muted=!a.doc.audio.muted);}
copy(){const keys=this.keys();if(!keys.length)return this.a.toast('Select keyframes first.');const min=Math.min(...keys.map(x=>x.k.time));this.clipboard=keys.map(x=>({id:x.n.id,prop:x.prop,key:clone(x.k),delta:x.k.time-min}));this.a.toast('Keyframes copied.');}
paste(){if(!this.clipboard.length)return this.a.toast('Copy keyframes first.');this.a.mutate('Paste keyframes',()=>{this.a.keyIds.clear();for(const x of this.clipboard){const n=find(this.a.doc,x.id),time=this.a.time+x.delta;if(n&&time<=this.a.doc.duration){const k=putKey(n,x.prop,time,x.key.value,x.key.easing);this.a.keyIds.add(k.id);}}});}
delete(){this.a.mutate('Delete keyframes',()=>{walk(this.a.doc.layers,n=>{for(const prop of Object.keys(n.tracks))n.tracks[prop]=n.tracks[prop].filter(k=>!this.a.keyIds.has(k.id));});this.a.keyIds.clear();});}
waveform(){const audio=this.a.doc.audio,buffer=this.a.audio?.buffer,canvas=this.el.querySelector('.audio-clip canvas');if(!canvas||!buffer||!audio)return;const w=Math.min(4000,Math.max(1,Math.ceil(canvas.parentElement.clientWidth)));canvas.width=w;canvas.height=32;const ctx=canvas.getContext('2d'),data=buffer.getChannelData(0),start=Math.floor(audio.trimStart*buffer.sampleRate),end=Math.floor(audio.trimEnd*buffer.sampleRate),chunk=Math.max(1,(end-start)/w);ctx.strokeStyle='#579887';ctx.beginPath();for(let x=0;x<w;x++){let max=0;const from=Math.floor(start+x*chunk),to=Math.min(data.length,Math.ceil(from+chunk));const step=Math.max(1,Math.floor((to-from)/30));for(let i=from;i<to;i+=step)max=Math.max(max,Math.abs(data[i]));const h=Math.max(1,max*14);ctx.moveTo(x+.5,16-h);ctx.lineTo(x+.5,16+h);}ctx.stroke();}
}
